package village.vale.culinary;
import net.minecraft.entity.player.*;import net.minecraft.inventory.*;import net.minecraft.item.ItemStack;import net.minecraft.tileentity.TileEntityFurnace;
/** Same slot order as vanilla single-row chest UI, with server-authoritative output slots. */
public final class KitchenContainer extends Container {
 final KitchenTile tile;KitchenContainer(InventoryPlayer inventory,KitchenTile t){tile=t;for(int i=0;i<9;i++){final int index=i;addSlotToContainer(new Slot(t,i,8+i*18,18){@Override public boolean isItemValid(ItemStack s){return index<4&&tile.isItemValidForSlot(index,s);}@Override public ItemStack onTake(EntityPlayer p,ItemStack taken){if(index==4&&!p.world.isRemote&&p instanceof EntityPlayerMP&&!p.capabilities.isCreativeMode&&!taken.isEmpty()&&taken.getItem() instanceof KitchenFood)village.vale.Missions.crafted((EntityPlayerMP)p,taken);return super.onTake(p,taken);}});}for(int row=0;row<3;row++)for(int col=0;col<9;col++)addSlotToContainer(new Slot(inventory,col+row*9+9,8+col*18,49+row*18));for(int col=0;col<9;col++)addSlotToContainer(new Slot(inventory,col,8+col*18,107));}
 @Override public boolean canInteractWith(EntityPlayer p){return tile.isUsableByPlayer(p);}
 @Override public ItemStack transferStackInSlot(EntityPlayer p,int index){if(index<0||index>=45||!canInteractWith(p))return ItemStack.EMPTY;Slot slot=inventorySlots.get(index);ItemStack live=slot.getStack();if(live.isEmpty())return ItemStack.EMPTY;ItemStack old=live.copy();boolean moved=index<9?mergeItemStack(live,9,45,true):TileEntityFurnace.getItemBurnTime(live)>0?mergeItemStack(live,3,4,false):mergeItemStack(live,0,3,false);if(!moved)return ItemStack.EMPTY;int removed=old.getCount()-live.getCount();if(live.isEmpty())slot.putStack(ItemStack.EMPTY);else slot.onSlotChanged();if(removed>0){ItemStack taken=old.copy();taken.setCount(removed);slot.onTake(p,taken);}return old;}
}
